def rstrip(self):
        # type: () -> str
        try:
            msg = '%s' % str(self)
        except UnicodeEncodeError:
            comment = self.comment
            self.comment = ''
            msg = '$ dropped comment due to unicode error\n%s' % str(self)
            self.comment = comment
        return msg.rstrip()

